        params = new URLSearchParams("=b&c=d");
        assert2.true(params.has(""));
        params = new URLSearchParams("null=a");
        assert2.true(params.has(null));
        params = new URLSearchParams("a=b&c=d&&");
        params.append("first", 1);
        params.append("first", 2);
        assert2.true(params.has("a"), 'search params object has name "a"');
        assert2.true(params.has("c"), 'search params object has name "c"');
        assert2.true(params.has("first"), 'search params object has name "first"');
        assert2.false(params.has("d"), 'search params object has no name "d"');
        params.delete("first");
        assert2.false(params.has("first"), 'search params object has no name "first"');
        params = new URLSearchParams("a=1&a=2&a=null&a=3&b=4");
