        params.append("", "");
        assert2.same(String(params), "a=&a=&=b&=");
        params.append("", "");
        assert2.same(String(params), "a=&a=&=b&=&=");
        params = new URLSearchParams();
        params.append("", "b");
        assert2.same(String(params), "=b");
        params.append("", "b");
        assert2.same(String(params), "=b&=b");
        params = new URLSearchParams();
        params.append("", "");
        assert2.same(String(params), "=");
        params.append("", "");
        assert2.same(String(params), "=&=");
        params = new URLSearchParams();
        params.append("a", "b+c");
        assert2.same(String(params), "a=b%2Bc");
        params.delete("a");
        params.append("a+b", "c");
        assert2.same(String(params), "a%2Bb=c");
        params = new URLSearchParams();
        params.append("=", "a");
        assert2.same(String(params), "%3D=a");
        params.append("b", "=");
        assert2.same(String(params), "%3D=a&b=%3D");
        params = new URLSearchParams();
        params.append("&", "a");
