        params.append("b", "&");
        assert2.same(String(params), "%26=a&b=%26");
        params = new URLSearchParams();
        params.append("a", "\r");
        assert2.same(String(params), "a=%0D");
        params = new URLSearchParams();
        params.append("a", "\n");
        assert2.same(String(params), "a=%0A");
        params = new URLSearchParams();
        params.append("a", "\r\n");
        assert2.same(String(params), "a=%0D%0A");
