        assert2.throws(() => new URL("http://1.2.3.4.5/"), "IPv4 with > 4 parts");
        assert2.throws(() => new URL("http://a.b.c.d.5/"), "host ending in number with non-numeric parts");
        assert2.throws(() => new URL("http://foo.1/"), "host ending in number with non-IPv4");
