        assert2.same(new URL("http://%30x7f.0.0.1/").hostname, "127.0.0.1", "percent-decoded hexadecimal IPv4 part");
        assert2.throws(() => new URL("http://a%D0/"), "percent sequence truncated by the end of a domain");
