        assert2.same(new URL("http://a\u{11FC0}b.example.com/").hostname, "xn--ab-ed4p.example.com", "supplementary code point sharing low units with the table");
        assert2.same(new URL("http://a\u{12100}b.example.com/").hostname, "xn--ab-t44p.example.com", "supplementary code point sharing low units with the table");
