      QUnit.test("URL#href", (assert2) => {
        let url = new URL("http://zloirock.ru/");
        if (DESCRIPTORS) {
          assert2.false(hasOwnProperty.call(url, "href"));
          const descriptor = Object.getOwnPropertyDescriptor(URL.prototype, "href");
          assert2.true(descriptor.enumerable);
          assert2.true(descriptor.configurable);
          assert2.same(typeof descriptor.get, "function");
          assert2.same(typeof descriptor.set, "function");
        }
        assert2.same(url.href, "http://zloirock.ru/");
        if (DESCRIPTORS) {
          url.searchParams.append("foo", "bar");
          assert2.same(url.href, "http://zloirock.ru/?foo=bar");
          url = new URL("http://zloirock.ru/foo");
          url.href = "https://\u6E2C\u8A66";
          assert2.same(url.href, "https://xn--g6w251d/", "unicode parsing");
          assert2.same(String(url), "https://xn--g6w251d/", "unicode parsing");
          url = new URL("http://zloirock.ru/foo");
          url.href = "https://xx\u043F\u0440\u0438\u0432\u0435\u0442.\u0442\u0435\u0441\u0442";
          assert2.same(url.href, "https://xn--xx-flcmn5bht.xn--e1aybc/", "unicode parsing");
          assert2.same(String(url), "https://xn--xx-flcmn5bht.xn--e1aybc/", "unicode parsing");
          url = new URL("http://zloirock.ru/foo");
          url.href = "https://xx\u041F\u0420\u0418\u0412\u0415\u0422.\u0442\u0435\u0441\u0442";
          assert2.same(url.href, "https://xn--xx-flcmn5bht.xn--e1aybc/", "unicode parsing");
          assert2.same(String(url), "https://xn--xx-flcmn5bht.xn--e1aybc/", "unicode parsing");
          url = new URL("http://zloirock.ru/");
          url.href = "http://0300.168.0xF0";
          assert2.same(url.href, "http://192.168.0.240/");
          assert2.same(String(url), "http://192.168.0.240/");
          url = new URL("http://zloirock.ru/");
          url.href = "http://[20:0:0:1:0:0:0:ff]";
          assert2.same(url.href, "http://[20:0:0:1::ff]/");
          assert2.same(String(url), "http://[20:0:0:1::ff]/");
          url = new URL("http://zloirock.ru/");
          url.href = "http://0300.168.0xG0";
          assert2.same(url.href, "http://0300.168.0xg0/", "incorrect IPv4 parsed as host");
          assert2.same(String(url), "http://0300.168.0xg0/", "incorrect IPv4 parsed as host");
          url = new URL("http://192.168.0.240/");
          url.href = "file:///var/log/system.log";
          assert2.same(url.href, "file:///var/log/system.log", "file -> ip");
          assert2.same(String(url), "file:///var/log/system.log", "file -> ip");
          url = new URL("file:///var/log/system.log");
          url.href = "http://0300.168.0xF0";
        }
      });
